cd /app && python3 - <<'PYEOF'
p='crates/wasmi/src/store/inner.rs'
s=open(p).read()
s=s.replace("""    /// The stacks of all currently active Wasm executions in this store.
    ///
    /// # Note
    ///
    /// The stacks are stored in order from outermost to innermost execution.
    active_stacks: Vec<*mut Stack>,
}""",
"""    /// The stacks of all currently active Wasm executions in this store.
    ///
    /// # Note
    ///
    /// - The stacks are stored in order from outermost to innermost execution.
    /// - The stacks are stored as raw `usize` addresses to keep [`StoreInner`]
    ///   `Send` and `Sync`.
    active_stacks: Vec<usize>,
}""")
s=s.replace("""    pub(crate) fn push_active_stack(&mut self, stack: *mut Stack) {
        self.active_stacks.push(stack);
    }

    /// Unregisters `stack` from the active Wasm execution stacks.
    pub(crate) fn pop_active_stack(&mut self, stack: *mut Stack) {
        let popped = self.active_stacks.pop();
        debug_assert_eq!(popped, Some(stack));
    }

    /// Returns the currently active Wasm execution stacks.
    ///
    /// # Note
    ///
    /// The stacks are ordered from outermost to innermost execution.
    pub(crate) fn active_stacks(&self) -> &[*mut Stack] {
        &self.active_stacks
    }""",
"""    pub(crate) fn push_active_stack(&mut self, stack: *mut Stack) {
        self.active_stacks.push(stack as usize);
    }

    /// Unregisters `stack` from the active Wasm execution stacks.
    pub(crate) fn pop_active_stack(&mut self, stack: *mut Stack) {
        let popped = self.active_stacks.pop();
        debug_assert_eq!(popped, Some(stack as usize));
    }

    /// Returns the currently active Wasm execution stacks.
    ///
    /// # Note
    ///
    /// The stacks are ordered from outermost to innermost execution.
    pub(crate) fn active_stacks(&self) -> &[usize] {
        &self.active_stacks
    }""")
open(p,'w').write(s)
PYEOF
